ransom-note:
class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        cnt = {}
        for c in magazine:
            cnt[c] = cnt.get(c, 0) + 1
        for c in ransomNote:
            if cnt.get(c, 0) == 0:
                return False
            cnt[c] -= 1
        return True

rectangle-overlap:
class Solution:
    def isRectangleOverlap(self, rec1: list[int], rec2: list[int]) -> bool:
        return rec1[0] < rec2[2] and rec2[0] < rec1[2] and rec1[1] < rec2[3] and rec2[1] < rec1[3]

relative-ranks:
class Solution:
    def findRelativeRanks(self, score: list[int]) -> list[str]:
        order = sorted(range(len(score)), key=lambda i: -score[i])
        out = [''] * len(score)
        medal = {0: 'Gold Medal', 1: 'Silver Medal', 2: 'Bronze Medal'}
        for rank, i in enumerate(order):
            out[i] = medal.get(rank, str(rank + 1))
        return out

relative-sort-array:
class Solution:
    def relativeSortArray(self, arr1: list[int], arr2: list[int]) -> list[int]:
        cnt = {}
        for v in arr1:
            cnt[v] = cnt.get(v, 0) + 1
        out = []
        for v in arr2:
            if cnt.get(v, 0):
                out.extend([v] * cnt[v])
                cnt[v] = 0
        for v in sorted(cnt):
            if cnt[v]:
                out.extend([v] * cnt[v])
        return out

remove-all-adjacent-duplicates-in-string:
class Solution:
    def removeDuplicates(self, s: str) -> str:
        st = []
        for c in s:
            if st and st[-1] == c:
                st.pop()
            else:
                st.append(c)
        return ''.join(st)

remove-palindromic-subsequences:
class Solution:
    def removePalindromeSub(self, s: str) -> int:
        if not s:
            return 0
        return 1 if s == s[::-1] else 2

replace-elements-with-greatest-element-o:
class Solution:
    def replaceElements(self, arr: list[int]) -> list[int]:
        best = -1
        out = [0] * len(arr)
        for i in range(len(arr) - 1, -1, -1):
            out[i] = best
            if arr[i] > best:
                best = arr[i]
        return out

reverse-bits:
class Solution:
    def reverseBits(self, n: int) -> int:
        res = 0
        for _ in range(32):
            res = (res << 1) | (n & 1)
            n >>= 1
        return res

reverse-only-letters:
class Solution:
    def reverseOnlyLetters(self, s: str) -> str:
        a = list(s)
        i = 0
        j = len(a) - 1
        while i < j:
            if not a[i].isalpha():
                i += 1
            elif not a[j].isalpha():
                j -= 1
            else:
                a[i], a[j] = a[j], a[i]
                i += 1
                j -= 1
        return ''.join(a)

reverse-prefix-of-word:
class Solution:
    def reversePrefix(self, word: str, ch: str) -> str:
        i = word.find(ch)
        if i < 0:
            return word
        return word[:i + 1][::-1] + word[i + 1:]

reverse-string:
class Solution:
    def reverseString(self, s: list[str]) -> None:
        i = 0
        j = len(s) - 1
        while i < j:
            s[i], s[j] = s[j], s[i]
            i += 1
            j -= 1

reverse-string-ii:
class Solution:
    def reverseStr(self, s: str, k: int) -> str:
        a = list(s)
        for i in range(0, len(a), 2 * k):
            a[i:i + k] = a[i:i + k][::-1]
        return ''.join(a)

reverse-vowels-of-a-string:
class Solution:
    def reverseVowels(self, s: str) -> str:
        vows = set('aeiouAEIOU')
        a = list(s)
        i = 0
        j = len(a) - 1
        while i < j:
            if a[i] not in vows:
                i += 1
            elif a[j] not in vows:
                j -= 1
            else:
                a[i], a[j] = a[j], a[i]
                i += 1
                j -= 1
        return ''.join(a)

reverse-words-in-a-string-iii:
class Solution:
    def reverseWords(self, s: str) -> str:
        return ' '.join(w[::-1] for w in s.split(' '))

richest-customer-wealth:
class Solution:
    def maximumWealth(self, accounts: list[list[int]]) -> int:
        best = 0
        for row in accounts:
            t = sum(row)
            if t > best:
                best = t
        return best
